jordan.update(name='Jordan River',summary='The behemoth poem names the Jordan when describing a swelling river.',limits='Reference marker for the river. Job’s home and the creature’s location are not placed here.',sourceIds=['web','atlas-canaan'])
lds={1:'Come, Follow Me reads the heavenly exchange as poetry about an accuser’s challenge.',2:'Come, Follow Me asks why faith should continue when expected rewards disappear.',3:'Come, Follow Me allows questions and faith to remain together during suffering.',4:'Come, Follow Me asks readers to examine the friends’ claim that pain proves guilt.',5:'Come, Follow Me questions the friends’ explanation that God is punishing Job.',8:'Come, Follow Me asks what goes wrong when friends explain pain through blame.',11:'Come, Follow Me questions Zophar’s claim that Job’s pain comes from wrongdoing.',12:'Come, Follow Me asks what Job knows about God while challenging his friends.',13:'Come, Follow Me follows the King James Bible’s reading about trusting God. WEB follows the other reading noted above.',14:'Come, Follow Me connects Job’s question about death with resurrection through Jesus Christ.',16:'Come, Follow Me asks how friends can strengthen someone instead of adding blame.',19:'Come, Follow Me reads Job’s Redeemer as Jesus Christ and invites reflection on resurrection.',21:'Come, Follow Me studies the contrast between wicked success and faithful suffering.',22:'Come, Follow Me uses Eliphaz’s accusation to ask how friends can offer better help.',23:'Come, Follow Me connects Job’s search with faith during unanswered questions.',24:'Come, Follow Me asks how Restoration scripture helps readers think about suffering.',31:'Come, Follow Me recalls Job’s repeated request for God to answer him.',38:'The Seminary lesson connects the joyful sons of God with life before birth.',39:'Come, Follow Me asks how the creatures in God’s speech change the reader’s view.',40:'Come, Follow Me asks readers to consider God’s creations from different views.',42:'The Seminary lesson connects Job’s prayer and renewed life with hope after loss.'}
questions={6:'Job asks for kindness before a verdict. How could his friends answer that request?',7:'Job speaks directly to God about pain. What does he ask God to change?',9:'Job wants someone to hear both sides. What prevents him from feeling heard?',10:'Job recalls the care that formed him. Why does his present pain make that memory difficult?',15:'Eliphaz treats protest as proof of guilt. What happens when listeners make that assumption?',17:'Job’s plans have broken apart. What kind of help could reach him now?',18:'Bildad describes the loss of a name and children. How might Job hear those words?',20:'Zophar links wickedness with brief success. What evidence would challenge his claim?',25:'Bildad speaks about human weakness. Does his answer address what Job asked?',26:'Job asks how Bildad helped him. What separates an impressive speech from useful comfort?',27:'Job refuses a false confession. Why would admitting his friends are right matter?',28:'The poem separates treasure from wisdom. What can skill and wealth fail to teach?',29:'Job remembers helping people in need. How does that memory answer Eliphaz’s accusations?',30:'Job’s neighbors add mockery to pain. What could they change without knowing why he suffers?',32:'Elihu waited for older speakers. Does his anger help him listen?',33:'Elihu says pain can teach. How could that idea help or hurt someone in distress?',34:'Elihu defends fairness while accusing Job. What evidence supports his charge?',35:'Elihu links unanswered cries with pride. What would Job’s earlier words challenge?',36:'Elihu promises good years after obedience. How does that promise compare with Job’s experience?',37:'Elihu asks about weather beyond human control. What changes when the next speaker is the Lord?',41:'The poem describes Leviathan beyond human control. What does that show about the limits of power?'}
chapters=[]
for n,(title,summary,meaning) in enumerate(rows,1):
 pids=['job']
 if n==1:pids+=['satan-job','job-first-children','job-messengers','sabeans-job','chaldeans-job']
 if n==2:pids+=['satan-job','job-wife','eliphaz-job','bildad','zophar']
 if n in [4,5,15,22]:pids+=['eliphaz-job']
 if n in [8,18,25]:pids+=['bildad']
 if n in [11,20]:pids+=['zophar']
 if n==19:pids+=['job-wife']
 if n==31:pids+=['job-wife','adam']
 if n in range(32,38):pids+=['elihu-job']
 if n==32:pids+=['barachel-family-job','eliphaz-job','bildad','zophar']
 if n==42:pids+=['eliphaz-job','bildad','zophar','jemimah','keziah','keren-happuch','job-later-sons','job-siblings']
 hs=[s['id'] for s in sources if s['perspective']=='historical' and n in s.get('chapterCoverage',[])]
 ls=[s['id'] for s in sources if s['perspective']=='lds' and n in s.get('chapterCoverage',[])]
 text=lds.get(n,questions[n] if n in questions else '')
 chapters.append(dict(chapter=n,title=title,summary=summary,meaning=meaning,people=pids,places=['jordan'] if n==40 else [],sourceIds=['web']+hs,lds=dict(text=text,sourceIds=ls),eventOrder=n,dateLabel='Chapter order',historicalNote=meaning,mapNote='The poem names the Jordan. This marker does not locate Job’s home.' if n==40 else 'Job’s home in Uz has no secure map location.',route=[],routeEvidence='No travel route is reconstructed.'))
finish(dict(id='job',bibleCode='JOB',name='Job',description='Loss · disputed blame · questions · renewed life',chapterCount=42,scripture=scripture('job','JOB',42),chapters=chapters,people=people,places=[jordan],sources=sources,review=dict(date='2026-10-05',scope='All 1,070 WEB verses reviewed. Speakers and claims are distinguished. Uz has no invented marker.',nextBook='psalms')))
